(()=>{'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],projects=window.PORTFOLIO_PROJECTS,config=window.PORTFOLIO_CONFIG,root=document.documentElement,reduce=matchMedia('(prefers-reduced-motion: reduce)');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const imageIcon='<svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m4 17 5-5 4 4 3-3 5 5"/></svg>';
function placeholder(p){return '<span class="placeholder">'+imageIcon+'<strong>Screenshot not available</strong><small>Visual placeholder</small></span>'}
function visual(p,index=0){const m=p.media[index];return m?'<img src="'+esc(m.src)+'" alt="'+esc(m.alt)+'" width="1440" height="900" loading="lazy">':placeholder(p)}
window.PORTFOLIO_VISUALS={placeholder,visual};
// Portfolio 5 navigation, with complete mobile expanded-state and Escape handling.
function closeMenu(focus=false){$('#links').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$('#menu').setAttribute('aria-label','Open navigation');if(focus)$('#menu').focus()}
$('#menu').onclick=()=>{const open=!$('#links').classList.contains('open');$('#links').classList.toggle('open',open);$('#menu').setAttribute('aria-expanded',String(open));$('#menu').setAttribute('aria-label',open?'Close navigation':'Open navigation')};
$$('#links a').forEach(a=>a.addEventListener('click',()=>closeMenu()));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#links').classList.contains('open'))closeMenu(true)});document.addEventListener('pointerdown',e=>{if(!e.target.closest('.nav'))closeMenu()});matchMedia('(min-width:861px)').addEventListener('change',e=>{if(e.matches)closeMenu()});
function setTheme(theme){root.dataset.theme=theme;$('#theme').setAttribute('aria-label',theme==='dark'?'Switch to light theme':'Switch to dark theme');$('#theme').setAttribute('aria-pressed',String(theme==='dark'))}
try{setTheme(localStorage.getItem('wafiy-hybrid-theme')==='dark'?'dark':'light')}catch{setTheme('light')}
$('#theme').onclick=()=>{const t=root.dataset.theme==='dark'?'light':'dark';setTheme(t);try{localStorage.setItem('wafiy-hybrid-theme',t)}catch{}};
let scrollFrame=0;function updateProgress(){scrollFrame=0;const max=root.scrollHeight-root.clientHeight;$('#bar').style.transform='scaleX('+(max>0?Math.min(1,root.scrollTop/max):0)+')'}addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(updateProgress)},{passive:true});updateProgress();
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){$$('#links a').forEach(a=>{const on=a.dataset.s===e.target.id;a.classList.toggle('on',on);if(on)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}},{rootMargin:'-15% 0px -65% 0px'});$$('main section[id]').forEach(s=>observer.observe(s))}

const capstone=projects.find(p=>p.id==='auto');
let filtered=[...projects],filter='all';
function renderProjects(){const q=$('#search').value.toLowerCase().trim();filtered=projects.filter(p=>(filter==='all'||p.category===filter)&&[p.title,p.summary,p.context,...p.tools].join(' ').toLowerCase().includes(q));$('#grid').innerHTML=filtered.map(p=>'<button type="button" class="card" data-id="'+p.id+'" aria-label="Open '+esc(p.title)+' case study"><span class="card-top"><span class="project-symbol" aria-hidden="true">'+({development:'&lt;/&gt;',data:'▥',design:'✳'}[p.category])+'</span><span class="project-arrow" aria-hidden="true">↗</span></span><span class="ct"><b>'+esc(p.title)+'</b><span>'+esc(p.summary)+'</span></span><span class="card-tools">'+p.tools.map(t=>'<span>'+esc(t)+'</span>').join('')+'</span><span class="cm"><span>'+esc(p.context)+'</span><span aria-hidden="true">Read story +</span></span></button>').join('');if(!filtered.length)$('#grid').innerHTML='<p class="empty">No projects match. Try a different keyword or select All projects.</p>';$('#projectCount').textContent=filtered.length+' '+(filtered.length===1?'project':'projects');document.dispatchEvent(new CustomEvent('portfolio:projectchange'))}
$$('#filters button').forEach(b=>b.onclick=()=>{filter=b.dataset.f;$$('#filters button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderProjects()});$('#search').oninput=renderProjects;renderProjects();
// Native dialog supplies modal semantics and focus isolation; retain P5's right-side drawer.
let activeProject=capstone,drawerList=projects,projectIndex=0,opener=null;
function projectLinkMarkup(p){const url=p.projectUrl||p.repository,platform=p.projectUrl?p.projectPlatform:'GitHub';return url?'<a class="btn p project-source" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">Go to project <span aria-hidden="true">↗</span><span class="visually-hidden"> on '+esc(platform)+' (opens in a new tab)</span></a>':'<p class="repository-status">'+esc(p.repositoryStatus||'A public project link is not available for this project.')+'</p>'}
function renderCase(){activeProject=drawerList[projectIndex];const p=activeProject;$('#cc').textContent=p.label+' / '+(projectIndex+1)+' of '+drawerList.length;$('#cb').innerHTML='<h2 id="ctitle">'+esc(p.title)+'</h2><p class="detail-summary">'+esc(p.summary)+'</p>'+projectLinkMarkup(p)+'<dl class="meta"><div><dt>Context</dt><dd>'+esc(p.context)+'</dd></div><div><dt>Role</dt><dd>'+esc(p.role)+'</dd></div><div><dt>Technologies</dt><dd>'+esc(p.tools.join(', '))+'</dd></div></dl><h3>The problem</h3><p>'+esc(p.problem)+'</p><h3>The approach</h3><ul>'+p.approach.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul><h3>Project context & outcome</h3><p class="res">'+esc(p.outcome)+'</p><p class="detail-note">'+esc(p.note)+'</p>';$('#case').scrollTop=0}
function openCase(id){const p=projects.find(p=>p.id===id);if(!p)return;opener=document.activeElement;drawerList=[...filtered];if(!drawerList.some(p=>p.id===id))drawerList=[p];projectIndex=drawerList.findIndex(p=>p.id===id);renderCase();document.dispatchEvent(new CustomEvent('portfolio:draweropen'));$('#scrim').classList.add('on');document.body.classList.add('modal-open');$('#case').showModal();requestAnimationFrame(()=>$('#case').classList.add('on'));$('#cx').focus({preventScroll:true})}
function closeCase(){$('#case').classList.remove('on');$('#case').close()}
$('#case').addEventListener('close',()=>{$('#scrim').classList.remove('on');document.body.classList.remove('modal-open');if(opener?.isConnected)opener.focus({preventScroll:true})});$('#case').addEventListener('cancel',e=>{e.preventDefault();closeCase()});$('#cx').onclick=closeCase;$('#scrim').onclick=closeCase;
function outsideClose(dialog,close){dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))close()})}outsideClose($('#case'),closeCase);
function trap(dialog){dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const focusable=$$('button:not([disabled]),a[href],input:not([disabled]),textarea,select,[tabindex="0"]',dialog).filter(x=>x.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}})}trap($('#case'));
$('#grid').onclick=e=>{const b=e.target.closest('[data-id]');if(b)openCase(b.dataset.id)};$$('[data-open]').forEach(b=>b.onclick=()=>openCase(b.dataset.open));$('#cpv').onclick=()=>{projectIndex=(projectIndex-1+drawerList.length)%drawerList.length;renderCase()};$('#cnx').onclick=()=>{projectIndex=(projectIndex+1)%drawerList.length;renderCase()};
// Contact copy action: report success only after the clipboard write succeeds.
$$('[data-linkedin]').forEach(a=>a.href=config.linkedin);
const copyButton=$('#copyContactEmail'),copyStatus=$('#copyStatus');
if(config.email){$('span',copyButton).textContent='Copy email address'}else{copyButton.disabled=true;$('span',copyButton).textContent='Email not configured';copyStatus.textContent='Add a professional email in config.js.'}
copyButton.addEventListener('click',async()=>{
  if(!config.email)return;
  try{await navigator.clipboard.writeText(config.email);copyStatus.textContent='Email copied.'}
  catch{copyStatus.replaceChildren(document.createTextNode('Copy this email: '+config.email+'. '));const link=document.createElement('a');link.href='mailto:'+config.email;link.textContent='Open email app';copyStatus.append(link)}
});
})();
